import 'package:flutter/material.dart';
class SummaryCard extends StatelessWidget {final String label,value;final IconData icon;final Color color;const SummaryCard({super.key,required this.label,required this.value,required this.icon,required this.color});@override Widget build(BuildContext c)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[CircleAvatar(backgroundColor:color.withValues(alpha:.12),child:Icon(icon,color:color)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:Theme.of(c).textTheme.labelMedium),const SizedBox(height:4),Text(value,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold))]))])));}
